if __name__=='__main__':
    from province_sources import apply_province_sources
    from enrich_legal_index import apply_legal_editorial
    apply_province_sources(rows)
    # Seeding must retain supplementary records, including local management notices.
    import csv
    previous = ROOT/'data/legal_documents.csv'
    by_id = {row['document_id']: row for row in rows}
    if previous.exists():
        for row in csv.DictReader(previous.open(encoding='utf-8-sig')):
            by_id.setdefault(row['document_id'],row)
    rows = apply_legal_editorial(list(by_id.values()))
    write_csv(ROOT/'data/legal_documents.csv',rows)
    print('Legal index:',len(rows),'documents')
